FUNCTION_BLOCK FB
VAR_INPUT
    enqueue : BOOL;
    dequeue : BOOL;
    reset : BOOL;
    capacity : DINT;
END_VAR
VAR_OUTPUT
    elementCount : DINT;
    status : WORD;
END_VAR
VAR_IN_OUT
    item : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR
VAR
    headIdx : DINT := 1;
    tailIdx : DINT := 1;
    cnt : DINT := 0;
    enqueue_prev : BOOL := FALSE;
    dequeue_prev : BOOL := FALSE;
    enqueue_rise : BOOL;
    dequeue_rise : BOOL;
    capEff : DINT;
END_VAR

// 限制有效容量到数组边界 1..4
capEff := capacity;
IF capEff < 1 THEN
    capEff := 1;
ELSIF capEff > 4 THEN
    capEff := 4;
END_IF

// 边沿检测并更新历史
enqueue_rise := enqueue AND NOT enqueue_prev;
dequeue_rise := dequeue AND NOT dequeue_prev;
enqueue_prev := enqueue;
dequeue_prev := dequeue;

// 默认无错误
status := 0;

IF reset THEN
    // 复位优先：清空队列，忽略入队/出队请求
    cnt := 0;
    headIdx := 1;
    tailIdx := 1;
ELSE
    // 处理入队请求
    IF enqueue_rise THEN
        IF cnt < capEff THEN
            buffer[tailIdx] := item;
            tailIdx := tailIdx + 1;
            IF tailIdx > capEff THEN
                tailIdx := 1;
            END_IF
            cnt := cnt + 1;
            status := 0;
        ELSE
            status := WORD#16#8002; // 满队入队被拒
        END_IF
    END_IF

    // 处理出队请求
    IF dequeue_rise THEN
        IF cnt > 0 THEN
            item := buffer[headIdx];
            headIdx := headIdx + 1;
            IF headIdx > capEff THEN
                headIdx := 1;
            END_IF
            cnt := cnt - 1;
            status := 0;
        ELSE
            status := WORD#16#8001; // 空队出队被拒
        END_IF
    END_IF
END_IF

// 更新输出计数
elementCount := cnt;

END_FUNCTION_BLOCK
